@Component
class QueueHealthIndicator implements HealthIndicator {
    public Health health() {
        int depth = queue.depth();
        return depth < 1000 ? Health.up().withDetail("depth", depth).build()
                            : Health.down().withDetail("depth", depth).build();
    }
}

